// Base64-encoded Bahij Janna Kurdish font (assets/fonts/BahijJanna-Regular.ttf & assets/fonts/BahijJanna-Bold.ttf).
//
// Print/export HTML documents (lib/*Template*.ts, lib/inventoryPDFReports.ts)
// are rendered by expo-print in an isolated WebView that has no access to the
// native font registry set up in app/_layout.tsx (that useFonts() call only
// covers React Native <Text>, not standalone HTML). Each PDF is a fully
// self-contained document, so the font has to be embedded directly as a
// data URI rather than loaded once and shared.
//
// Kurdish text uses 'Bahij Janna' (Regular 400 and Bold 700).
// English/Latin text renders with modern clean sans-serif ('Inter', system fonts).
// Aliases for 'Rudaw' and 'RudawRegular' are preserved so any legacy templates or rules
// immediately render in Bahij Janna without regressions.

const BAHIJ_JANNA_REGULAR_BASE64 =
  '';

const BAHIJ_JANNA_BOLD_BASE64 =
  '';

